#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
# 開始の時刻の形式が違う: 断られ、exit 2、何も保存しない
out=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 9am 10:00 x 2>&1 >/dev/null); rc=$?
[ "$rc" = 2 ] || { echo "start 9am: exit $rc, expected 2"; fail=1; }
case "$out" in *"bad time: 9am"*) ;; *) echo "start 9am: no bad time message: $out"; fail=1 ;; esac
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
# 終了の時刻の形式が違う: 断られ、exit 2、何も保存しない
out=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11am x 2>&1 >/dev/null); rc=$?
[ "$rc" = 2 ] || { echo "end 11am: exit $rc, expected 2"; fail=1; }
case "$out" in *"bad time: 11am"*) ;; *) echo "end 11am: no bad time message: $out"; fail=1 ;; esac
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
rm -f "$t"; exit $fail

